GET matters-acme-00123/_search
{
  "size": 8,
  "retriever": {
    "rrf": {
      "rank_constant": 60,
      "rank_window_size": 50,
      "retrievers": [
        { "standard": { "query": { "bool": {
            "must":   { "match": { "text": "termination for convenience notice period" } },
            "filter": [ { "term": { "matter_id": "acme-00123" } },
                        { "term": { "privileged": false } } ] } } } },
        { "knn": {
            "field": "vector", "k": 50, "num_candidates": 200,
            "query_vector_builder": { "text_embedding": {
                "model_id": "titan-v2", "model_text": "can we exit without penalty" } },
            "filter": [ { "term": { "matter_id": "acme-00123" } },
                        { "term": { "privileged": false } } ] } }
      ]
    }
  }
}

GET matters-*/_search
{
  "retriever": {
    "text_similarity_reranker": {
      "inference_id": "cohere-rerank-3-5",
      "inference_text": "notice period for termination for convenience",
      "field": "text",
      "rank_window_size": 50,
      "retriever": {
        "rrf": {
          "rank_window_size": 50,
          "retrievers": [
            { "standard": { "query": { "match": { "text": "termination convenience notice" } } } },
            { "knn": { "field": "vector", "k": 50, "num_candidates": 200,
                       "query_vector": "<query embedding>" } }
          ]
        }
      },
      "filter": { "bool": { "filter": [
        { "terms": { "matter_id": "<from entitlement service, never the request body>" } },
        { "term":  { "privileged": false } } ] } }
    }
  }
}

PUT matters-acme-00123-v2
{
  "mappings": {
    "properties": {
      "text":       { "type": "text", "analyzer": "english" },
      "matter_id":  { "type": "keyword" },
      "privileged": { "type": "boolean" },
      "doc_date":   { "type": "date" },
      "section":    { "type": "keyword" },
      "embed_model": { "type": "keyword" },        // e.g. titan-embed-text-v2:0/1024
      "vector": {
        "type": "dense_vector",
        "dims": 1024,
        "similarity": "cosine",
        "index_options": { "type": "bbq_hnsw", "m": 16, "ef_construction": 100 }
      }
    }
  }
}

